MOD = 10**9 + 7

def count_valid_sequences(n):
    dp = [0] * (n + 1)
    dp[0] = 1
    stack = []

    for i in range(1, n + 1):
        if i % 2 == 1:
            dp[i] = 0
            continue
        dp[i] = 0
        for j in range(i):
            if j % 2 == 1:
                continue
            dp[i] += dp[j] * dp[i - j - 2]
            dp[i] %= MOD
    return dp

